# Development
Work in this checkout and keep tests offline and deterministic.
Run `node --test tests/*.test.mjs`. Preserve public interfaces and existing tests.
Do not modify dependency/build configuration or inspect benchmark
machinery, grading artifacts or files outside this repository.
import test from "node:test";
import assert from "node:assert/strict";
import * as core0 from "../src/edge_touch.ts";
test("edge-touch",()=>{assert.equal(core0.overlaps({left:0,top:0,right:2,bottom:2},{left:1,top:1,right:3,bottom:3}),true);});
test("edge-touch-ordinary-0",()=>{assert.equal(core0.overlaps({left:0,top:0,right:1,bottom:1},{left:3,top:3,right:4,bottom:4}),false);});
test("edge-touch-ordinary-1",()=>{assert.equal(core0.overlaps({left:0,top:0,right:1,bottom:1},{left:0,top:0,right:1,bottom:1}),true);});
import * as core1 from "../src/normalized_bounds.ts";
import * as api1 from "../src/normalized_bounds_api.ts";
test("normalized-bounds",()=>{assert.deepEqual(api1.rectangleBounds({x1:0,y1:0,x2:0,y2:0}),{left:0,top:0,right:0,bottom:0});});
test("normalized-bounds-ordinary-0",()=>{assert.deepEqual(core1.normalizeBounds(0,0,0,0),{left:0,top:0,right:0,bottom:0});});
test("normalized-bounds-ordinary-1",()=>{assert.deepEqual(api1.rectangleBounds({x1:1,y1:0,x2:1,y2:2}),{left:1,top:0,right:1,bottom:2});});
